package com.shambasmart.domain.usecase.weather`n`nimport com.shambasmart.data.local.entity.WeatherLog`nimport com.shambasmart.domain.repository.WeatherRepository`nimport kotlinx.coroutines.flow.Flow`nimport javax.inject.Inject`n`nclass GetWeatherForecastUseCase @Inject constructor(`n    private val weatherRepository: WeatherRepository`n) {`n    operator fun invoke(): Flow<List<WeatherLog>> {`n        return weatherRepository.getAllWeatherLogs()`n    }`n`n    suspend fun getById(id: Long): Result<WeatherLog?> {`n        return try {`n            val weatherLog = weatherRepository.getWeatherLogById(id)`n            Result.success(weatherLog)`n        } catch (e: Exception) {`n            Result.failure(e)`n        }`n    }`n`n    fun getRecent(limit: Int): Flow<List<WeatherLog>> {`n        return weatherRepository.getRecentWeatherLogs(limit)`n    }`n}
